# PO and quotation share the Invoice schema
SCHEMAS = dict(invoice=Invoice, purchase_order=Invoice, quote=Invoice, receipt=Receipt,
               catalogue=Catalogue, contract=Contract, resume=Resume, paper=Paper,
               meeting_notes=MeetingNotes, other=Summary)

FIELD_TYPES = {'str':str, 'text':str, 'int':int, 'float':float, 'number':float, 'num':float, 'bool':bool,
               'list':list, 'dict':dict, 'strs':list[str], 'dicts':list[dict],
               'list[str]':list[str], 'list[dict]':list[dict]}
_DFLT = {str: '', int: 0, float: 0.0, bool: False}

# %% ../nbs/01_schema.ipynb #7ab433ab
def dyn_schema(spec,                    # 'vendor:str, total:float, items:dicts', or {'vendor':'str'}, or ['vendor']
               name:str='Extracted',    # class name, which the model sees
               doc:str=None,            # class docstring, which the model also sees
) -> type:
    'A dataclass built at runtime from a field spec: the shape of an answer, named in one string.'
    if isinstance(spec, str): spec = [p for p in re.split(r'[,\n]', spec) if p.strip()]
    if isinstance(spec, dict): spec = [f'{k}:{v}' for k, v in spec.items()]
    flds = []
    for p in spec:
        nm, _, ty = (p if isinstance(p, str) else ':'.join(p)).partition(':')
        t = FIELD_TYPES.get(ty.strip().lower() or 'str', str)
        flds.append((re.sub(r'\W', '_', nm.strip()), t, _DFLT.get(t, None)))
    if not flds: raise ValueError(f'no fields in schema spec {spec!r}')
    return make_dataclass(re.sub(r'\W', '', name) or 'Extracted', flds,
                          namespace=dict(__doc__=doc or 'The fields to pull out of the document.'))

# %% ../nbs/01_schema.ipynb #86058550
def as_schema(spec, name:str='Extracted', doc:str=None) -> type:
    'Whatever names a shape, as a dataclass: a `SCHEMAS` key, a dataclass, or a `dyn_schema` spec.'
    if is_dataclass(spec): return spec
    if isinstance(spec, str) and spec.strip() in SCHEMAS: return SCHEMAS[spec.strip()]
    return dyn_schema(spec, name=name, doc=doc)

# %% ../nbs/01_schema.ipynb #393a81bb
def _norm(obj, schema) -> dict:
    "A structured reply as a plain dict, with the `None` a list field defaults to turned back into `[]`."
    d = asdict(obj) if is_dataclass(obj) and not isinstance(obj, type) else dict(obj or {})
    lists = {f.name for f in fields(schema) if f.type is list or get_origin(f.type) is list}
    return {k: ([] if v is None and k in lists else v) for k, v in d.items()}

# %% ../nbs/01_schema.ipynb #6643e3bd001840f4
DATE_FIELDS = ('date', 'dates', 'due', 'due_date', 'start_date', 'end_date', 'effective_date',
               'expiry', 'expiry_date', 'renewal', 'updated', 'issued', 'period_start', 'period_end')
YEAR_FIELDS = ('year',)
MONEY_FIELDS = ('subtotal', 'tax', 'total', 'amount', 'price', 'unit_price', 'balance',
                'discount', 'shipping', 'paid', 'due_amount')
CURRENCIES = {'$': 'USD', 'US$': 'USD', '€': 'EUR', '£': 'GBP', '₹': 'INR', '¥': 'JPY'}
_MONTHS = {m: i+1 for i, m in enumerate(
    ('jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'))}

_ISO  = re.compile(r'^(\d{4})-(\d{1,2})-(\d{1,2})$')
_NUM3 = re.compile(r'^(\d{1,4})[/.\-](\d{1,2})[/.\-](\d{2,4})$')
_MD   = re.compile(r'^([a-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(\d{2,4}))?$', re.I)
_DM   = re.compile(r'^(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]{3,9})\.?(?:,?\s*(\d{2,4}))?$', re.I)
_MY   = re.compile(r'^([a-z]{3,9})\.?\s+(\d{4})$', re.I)
_YEAR = re.compile(r'^(\d{4})$')
_YEAR4 = re.compile(r'\d{4}')
_MAIL = re.compile(r'^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$')
_MONEY = re.compile(r'-?\d[\d,]*(?:\.\d+)?')
_TIME = re.compile(r'[T ]\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?\s*(?:Z|[+-]\d{2}:?\d{2})?$')

def _yr(y, ref:int) -> int:
    'A two-digit year read against the century the document itself sits in.'
    y = int(y)
    return y if y >= 100 else (ref // 100) * 100 + y

def _mon(w:str) -> int|None: return _MONTHS.get(w[:3].lower())

def date_order(vals) -> str|None:
    "Whether this document writes `dd/mm` or `mm/dd`, from whichever of its own dates has a part over 12."
    for v in vals:
        if (m := _NUM3.match(str(v or '').strip())) and len(m.group(1)) != 4:
            if int(m.group(1)) > 12: return 'dmy'
            if int(m.group(2)) > 12: return 'mdy'

def iso_date(v,               # whatever a model put in a date field
             ref:int=None,    # the year the document was stored under; supplies a year the value omits
             order:str=None   # 'dmy' or 'mdy' from `date_order`, to read 01/03/2024 the way the document does
) -> tuple:
    "One date as `(YYYY-MM-DD, why)`. `why` is set and the date is `''` when it cannot be read."
    from datetime import date, datetime
    s = re.sub(r'\s+', ' ', str(v or '')).strip().rstrip('.')
    s = _TIME.sub('', s)   # a model asked for a date sometimes answers with an ISO instant
    ref = ref or datetime.now().year
    if not s: return '', None
    mk = lambda y, m, d: (date(int(y), int(m), int(d)).isoformat(), None)
    try:
        if (m := _ISO.match(s)):  return mk(*m.groups())
        if (m := _MY.match(s)) and _mon(m.group(1)): return mk(m.group(2), _mon(m.group(1)), 1)
        if (m := _MD.match(s)) and _mon(m.group(1)):
            return mk(_yr(m.group(3) or ref, ref), _mon(m.group(1)), m.group(2))
        if (m := _DM.match(s)) and _mon(m.group(2)):
            return mk(_yr(m.group(3) or ref, ref), _mon(m.group(2)), m.group(1))
        if (m := _YEAR.match(s)): return mk(m.group(1), 1, 1)
        if (m := _NUM3.match(s)):
            a, b, c = m.groups()
            if len(a) == 4: return mk(a, b, c)                       # 2024-3-4 with slashes
            if int(a) > 12 or order == 'dmy': return mk(_yr(c, ref), b, a)
            if int(b) > 12 or order == 'mdy': return mk(_yr(c, ref), a, b)
            return '', f'{s!r} is day/month ambiguous'
    except ValueError: return '', f'{s!r} is not a calendar date'
    return '', f'{s!r} is not a date'

def money(v) -> tuple:
    'One amount as `(float, why)`. Strips the currency and the thousands separator the prompt forbade.'
    if isinstance(v, bool): return 0.0, f'{v!r} is not an amount'
    if isinstance(v, (int, float)): return float(v), None
    s = str(v or '').strip()
    if not s: return 0.0, None
    if not (m := _MONEY.search(s)): return 0.0, f'{s!r} is not an amount'
    n = float(m.group(0).replace(',', ''))
    return (-n if s.startswith('(') and s.endswith(')') else n), None


# %% ../nbs/01_schema.ipynb #ffe96fc6247147a2
BLANKS = {'n/a', 'na', 'none', 'null', 'nil', 'unknown', 'not stated', 'not specified', 'tbd', '-', '--'}
ROW_MONEY = ('amount', 'unit_price', 'price', 'qty', 'quantity')

def _err(f, v, why) -> AttrDict: return AttrDict(field=f, value=v, why=why)
def _is_rows(t) -> bool: return get_origin(t) is list and get_args(t)[:1] == (dict,)
def _is_list(t) -> bool: return t is list or get_origin(t) is list
def _blank(v): return '' if isinstance(v, str) and v.strip().lower() in BLANKS else v

def _field_kind(nm:str) -> str:
    'What a field name says it holds. Names, not schemas, so a `dyn_schema` field is checked too.'
    for k, ns in (('date', DATE_FIELDS), ('year', YEAR_FIELDS), ('money', MONEY_FIELDS),
                  ('email', ('email',)), ('currency', ('currency',))):
        if nm in ns: return k
    return ''

def _scalar(kind:str, v, yr:int, order:str=None) -> tuple:
    'One scalar read as what its name says it holds, and why it could not be.'
    v = _blank(v)
    if kind == 'date':  return iso_date(v, yr, order)
    if kind == 'money': return money(v)
    if kind == 'year':
        y = str(v or '').strip()
        if not y: return '', None
        # '2023-2024' is a volume, not a broken year: the first one it names is the year
        return (m.group(0), None) if (m := _YEAR4.search(y)) else ('', f'{y!r} is not a year')
    if kind == 'email':
        e = str(v or '').strip()
        return (e, None) if not e or _MAIL.match(e) else ('', f'{e!r} is not an email address')
    c = CURRENCIES.get(str(v or '').strip(), str(v or '').strip().upper())
    return ('', None) if not c else (c, None) if len(c) == 3 else ('', f'{c!r} is not a currency code')

def _typed(t, v) -> tuple:
    'A value forced into the type its field declares.'
    if _is_list(t): return ([] if v is None else list(v) if isinstance(v, (list, tuple)) else [v]), None
    if t in (float, int):
        n, why = money(_blank(v))
        return (int(n) if t is int else n), why
    if t is str: return (', '.join(map(str, v)) if isinstance(v, (list, tuple)) else _blank(v)), None
    return v, None

def _row(nm:str, r, errs:L) -> dict:
    'The money and quantity keys of one line item, read like their top-level namesakes.'
    if not isinstance(r, dict):
        errs.append(_err(f'{nm}[]', r, 'a line item that is not an object'))
        return r
    out = dict(r)
    for k in ROW_MONEY:
        if out.get(k) in (None, ''): continue
        n, why = money(out[k])
        if why: errs.append(_err(f'{nm}[].{k}', out[k], why))
        else: out[k] = int(n) if k in ('qty', 'quantity') and n == int(n) else n
    return out

def _sums(f:dict) -> L:
    'subtotal + tax is total, when the document states all three.'
    s, t, tot = (f.get(k) for k in ('subtotal', 'tax', 'total'))
    num = lambda x: x if isinstance(x, (int, float)) and not isinstance(x, bool) else 0
    s, t, tot = num(s), num(t), num(tot)
    if not (s and tot) or abs(s + t - tot) <= max(0.02, 0.01 * abs(tot)): return L()
    return L([_err('total', tot, f'subtotal {s} + tax {t} is {round(s + t, 2)}')])

def check_fields(schema,          # the dataclass the fields were pulled for
                 flds:dict,       # what the model returned
                 ref:float=None,  # epoch seconds of the document itself; supplies a year a date omits
) -> tuple:
    'Fields with dates as ISO and amounts as numbers, and an error per value that could not be read.'
    from datetime import datetime
    yr = datetime.fromtimestamp(ref).year if ref else None
    types, out, errs = {f.name: f.type for f in fields(schema)}, dict(flds or {}), L()
    dates = [v for nm, v in out.items() if _field_kind(nm) == 'date' and not _is_list(types.get(nm, str))]
    order = date_order(dates)
    for nm, v in list(out.items()):
        t, kind = types.get(nm, str), _field_kind(nm)
        if _is_list(t):
            v = _typed(t, v)[0]
            if kind == 'date':
                got = [iso_date(x, yr, order) for x in v]
                errs += L(_err(nm, x, w) for x, (_, w) in zip(v, got) if w)
                v = [d for d, w in got if d]
            elif _is_rows(t): v = [_row(nm, r, errs) for r in v]
            out[nm] = v
            continue
        v2, why = _scalar(kind, v, yr, order) if kind else _typed(t, v)
        if why: errs.append(_err(nm, v, why))
        out[nm] = v2
    return out, errs + _sums(out)


# %% ../nbs/01_schema.ipynb #d62421fb
def schema_str(schema) -> str:
    "A schema written out for a model to read: its docstring, then `name: type` per field."
    def ty(t):
        if isinstance(t, str): return t
        return str(t).replace('typing.', '') if get_origin(t) else getattr(t, '__name__', str(t))
    return ((schema.__doc__ or '').strip() + '\n\n{\n'
            + ',\n'.join(f'  "{f.name}": {ty(f.type)}' for f in fields(schema)) + '\n}')

# %% ../nbs/01_schema.ipynb #3dae58c8
def _split_reasoning(text:str) -> str:
    "The answer with any reasoning stripped: rishi's `split_think`, plus the *closing*-only tag an MLX prefill leaves."
    from urai import split_think
    text, _ = split_think(text)
    if '</think>' in text: text = text.partition('</think>')[2]
    return text.strip()

# %% ../nbs/01_schema.ipynb #bf7b950f
def _json_reply(ch, prompt:str, schema, sp:str='') -> object:
    'Ask for the shape as a JSON object in prose and rebuild it, with the model left unconstrained.'
    ch.hist = []
    from urai import resp_text, extract_fence
    txt = resp_text(ch(f'{sp}\n\n{prompt}\n\nReply with only a JSON object in a ```json fence, with '
                       f'exactly these keys and types:\n\n{schema_str(schema)}'))
    d = json.loads(extract_fence(_split_reasoning(txt), 'json'))
    nms = {f.name for f in fields(schema)}
    return schema(**{k: v for k, v in d.items() if k in nms})

